insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"epionce","slug":"gentle-cream-cleanser","title_zh_hk":"\u6ecb\u6f64\u6f54\u9762\u4e73","title_zh_cn":"\u6ecb\u6da6\u6d01\u9762\u4e73","title_en":"Gentle Cream Cleanser","description_zh_hk":"<p>\u76ae\u819a\u985e\u578b\uff1a\u4e7e\u6027/\u654f\u611f\u81f3\u4e00\u822c\u808c\u819a\u00a0 Dry/Sensitive to Normal Skin</p>\n\n<p>\u6ecb\u6f64\u6f54\u9762\u4e73\u6eab\u548c\u5730\u5378\u599d\uff0c\u6eb6\u89e3\u6c61\u67d3\u7269\uff0c\u7d30\u83cc\uff0c\u5875\u57a2\u53ca\u5176\u4ed6\u96dc\u8cea\u3002\u9019\u6b3e\u8212\u7de9\u6f54\u9762\u4e73\u6df1\u5c64\u6e05\u6f54\u9762\u90e8\uff0c\u800c\u4e14\u4e0d\u640d\u5bb3\u76ae\u819a\u4fdd\u8b77\u5c64\u529f\u80fd\uff0c\u4ea6\u4e0d\u6703\u523a\u6fc0\u6216\u4ee4\u808c\u819a\u4e7e\u71e5\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u63d0\u5347\u808c\u819a\u5929\u7136\u4fdd\u8b77\u5c64\u529f\u80fd\uff0c\u5e6b\u52a9\u9810\u9632\u6162\u6027\u53ca\u7834\u58de\u6027\u708e\u75c7\u3002</p>\n<p>\u2013 \u7279\u5225\u9069\u5408\u5b8c\u6210\u91ab\u5b78\u7642\u7a0b\u5f8c\u6f54\u819a\u4e4b\u7528\u3002</p>\n<p>\u2013 \u9069\u5408\u739f\u7470\u75e4\u7621\u53ca\u5176\u4ed6\u76ae\u819a\u554f\u984c\u5fb5\u72c0\u7528\u8005\u4f7f\u7528\u3002</p>\n<p>\u2013 \u9069\u7528\u65bc\u4e7e\u6027\u53ca/\u6216\u654f\u611f, \u53ca\u53d7\u640d\u808c\u819a\u3002</p>\n\n<p>\u4e3b\u8981\u6210\u5206</p>\n<p>\u2013 \u8700\u8475\u63d0\u53d6\u7269</p>\n<p>\u2013 \u68d7\u5b50\u63d0\u53d6\u7269</p>\n<p>\u2013 \u5421\u5576\u786b\u916e\u92c5</p>","description_zh_cn":"<p>\u76ae\u80a4\u7c7b\u578b\uff1a\u5e72\u6027/\u654f\u611f\u81f3\u4e00\u822c\u808c\u80a4\u00a0 Dry/Sensitive to Normal Skin</p>\n\n<p>\u6ecb\u6da6\u6d01\u9762\u4e73\u6e29\u548c\u5730\u5378\u5986\uff0c\u6eb6\u89e3\u6c61\u67d3\u7269\uff0c\u7ec6\u83cc\uff0c\u5c18\u57a2\u53ca\u5176\u4ed6\u6742\u8d28\u3002\u8fd9\u6b3e\u8212\u7f13\u6d01\u9762\u4e73\u6df1\u5c42\u6e05\u6d01\u9762\u90e8\uff0c\u800c\u4e14\u4e0d\u635f\u5bb3\u76ae\u80a4\u4fdd\u62a4\u5c42\u529f\u80fd\uff0c\u4ea6\u4e0d\u4f1a\u523a\u6fc0\u6216\u4ee4\u808c\u80a4\u5e72\u71e5\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u63d0\u5347\u808c\u80a4\u5929\u7136\u4fdd\u62a4\u5c42\u529f\u80fd\uff0c\u5e2e\u52a9\u9884\u9632\u6162\u6027\u53ca\u7834\u574f\u6027\u708e\u75c7\u3002</p>\n<p>\u2013 \u7279\u522b\u9002\u5408\u5b8c\u6210\u533b\u5b66\u7597\u7a0b\u540e\u6d01\u80a4\u4e4b\u7528\u3002</p>\n<p>\u2013 \u9002\u5408\u739f\u7470\u75e4\u75ae\u53ca\u5176\u4ed6\u76ae\u80a4\u95ee\u9898\u5f81\u72b6\u7528\u8005\u4f7f\u7528\u3002</p>\n<p>\u2013 \u9002\u7528\u4e8e\u5e72\u6027\u53ca/\u6216\u654f\u611f, \u53ca\u53d7\u635f\u808c\u80a4\u3002</p>\n\n<p>\u4e3b\u8981\u6210\u5206</p>\n<p>\u2013 \u8700\u8475\u63d0\u53d6\u7269</p>\n<p>\u2013 \u67a3\u5b50\u63d0\u53d6\u7269</p>\n<p>\u2013 \u5421\u5576\u786b\u916e\u950c</p>","description_en":"<p>Skin type: dry / sensitive to normal</p>\n<p>Gently removes makeup, pollutants, bacteria and dirt without compromising the barrier, irritating or drying the skin.</p>\n<p>Key benefits</p>\n<p>\u2013 Supports the natural barrier and helps prevent chronic inflammation</p>\n<p>\u2013 Suitable after medical treatments</p>\n<p>\u2013 Suitable for rosacea and other skin concerns</p>\n<p>\u2013 For dry, sensitive and compromised skin</p>\n<p>Key ingredients</p>\n<p>\u2013 Marshmallow extract</p>\n<p>\u2013 Date extract</p>\n<p>\u2013 Zinc pyrithione</p>","price_hkd":280,"stock":20,"image_paths":["/images/products/prod-15@2x.jpg"],"sort":215}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;